<?php
declare(strict_types=1);
require __DIR__.'/../app/bootstrap.php';
use App\Core\{Auth,Authorization as A,Csrf,Database as DB,Validator as V};
use App\Services\{CourseAssignmentService as C,AssignmentAccessService as Access,ContentImageService as Images,ManagementService as M};
$user=Auth::requireLogin();if(!A::isAdmin()&&!A::isTeacher())forbidden();$error=null;
if(is_post()){
    Csrf::verifyRequest();if(!A::isAdmin())forbidden();
    try{
        $course=V::int($_POST['course_id']??'','Course',1);$active=V::inList($_POST['active']??'1',['0','1'],'Active')==='1';$confirmed=($_POST['confirm_removal']??'')==='1';
        if(!$active&&!$confirmed)throw new DomainException('Confirm assignment deactivation first.');
        switch(request_action()){
            case 'centre_course':C::setCentreCourse(V::int($_POST['centre_id']??'','Centre',1),$course,$active);break;
            case 'batch_course':C::setBatchCourse(V::int($_POST['batch_id']??'','Batch',1),$course,$active);break;
            case 'batch_subjects':$ids=$_POST['subject_ids']??[];if(!is_array($ids))throw new DomainException('Invalid subjects.');C::setBatchSubjects(V::int($_POST['batch_id']??'','Batch',1),$course,$ids,$confirmed);break;
            case 'teacher_tuple':C::setTeacherAssignment(V::int($_POST['teacher_id']??'','Teacher',1),V::int($_POST['batch_id']??'','Batch',1),$course,V::int($_POST['subject_id']??'','Subject',1),$active);break;
            default:throw new DomainException('Unknown action.');
        }
        flash('success','Assignment saved.');redirect_self();
    }catch(Throwable $e){$error=handle_exception($e);}
}
if(A::isAdmin()){
$p=[];$scope=A::centreWhere('id',$p);$centres=DB::all("SELECT id,name FROM centres WHERE $scope ORDER BY name",$p);$centre=V::optInt($_GET['centre_id']??null,'Centre');
if($centre&&!A::canAccessCentre($centre))forbidden();$batch=V::optInt($_GET['batch_id']??null,'Batch');$selectedBatch=$batch?M::find('batches',$batch):null;
if($batch&&(!$selectedBatch||$centre&&(int)$selectedBatch['centre_id']!==$centre))not_found();if($selectedBatch)$centre=(int)$selectedBatch['centre_id'];
}
page_header(A::isTeacher()?'My teaching assignments':'Course assignments');
if($error)echo '<div class="flash flash-error" role="alert">'.e(tr($error)).'</div>';
if(A::isTeacher()){
    $rows=Access::teacherAssignments((int)$user['id']);
    echo '<div class="catalogue-grid">';foreach($rows as $r){$names=DB::one('SELECT b.name AS batch,c.name AS course,s.name AS subject FROM batches b JOIN courses c ON c.id=? JOIN subjects s ON s.id=? WHERE b.id=?',[$r['course_id'],$r['subject_id'],$r['batch_id']]);echo '<section class="card"><h2>'.e($names['subject']).'</h2><p>'.e($names['course']).' · '.e($names['batch']).'</p><a class="btn" href="modules.php?subject_id='.(int)$r['subject_id'].'">'.e(tr('Modules')).'</a></section>';}
    echo '</div>';if(!$rows)echo '<section class="card empty-state">'.e(tr('No explicit teaching assignments yet. Contact Admin.')).'</section>';page_footer();exit;
}
?>
<p class="muted catalogue-note"><?= e(tr('Assignments reuse global content. Deactivation preserves learning history. Restoring a parent can restore its retained assignments.')) ?></p>
<section class="card"><form method="get" class="filter-bar"><label><?= e(tr('Centre')) ?><select name="centre_id" required><option value=""><?= e(tr('Select')) ?></option><?php foreach($centres as $c): ?><option value="<?= (int)$c['id'] ?>"<?= selected($c['id'],$centre??'') ?>><?= e($c['name']) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary"><?= e(tr('Load centre')) ?></button></form>
<?php if($centre): $batches=DB::all('SELECT id,name,is_active FROM batches WHERE centre_id=? ORDER BY name',[$centre]); ?><form method="get" class="filter-bar"><input type="hidden" name="centre_id" value="<?= $centre ?>"><label><?= e(tr('Batch')) ?><select name="batch_id" required><option value=""><?= e(tr('Select')) ?></option><?php foreach($batches as $b): ?><option value="<?= (int)$b['id'] ?>"<?= selected($b['id'],$batch??'') ?>><?= e($b['name']).(!$b['is_active']?' · '.e(tr('inactive')):'') ?></option><?php endforeach; ?></select></label><button class="btn"><?= e(tr('Load batch')) ?></button><a class="btn" href="batches.php?new=1&amp;centre_id=<?= $centre ?>"><?= e(tr('Add batch')) ?></a></form><?php endif; ?></section>
<?php if(!$centre){page_footer();exit;}
$available=DB::all('SELECT c.*,cc.is_active AS centre_active FROM courses c LEFT JOIN centre_courses cc ON cc.course_id=c.id AND cc.centre_id=? '.(A::isSuperAdmin()?'':'WHERE cc.course_id IS NOT NULL').' ORDER BY c.name LIMIT 200',[$centre]);
?>
<?php if(A::isSuperAdmin()): ?><section class="card"><h2><?= e(tr('Centre course availability')) ?></h2><div class="assignment-columns"><?php foreach($available as $c): ?><article class="assignment-choice"><?= Images::thumbnail($c['cover_asset_id']??null,'',true) ?><span><strong><?= e($c['name']) ?></strong><br><?= e(tr($c['centre_active']?'Available':'Not assigned')) ?></span><form method="post"><?= csrf_field() ?><input type="hidden" name="action" value="centre_course"><input type="hidden" name="centre_id" value="<?= $centre ?>"><input type="hidden" name="course_id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="active" value="<?= $c['centre_active']?0:1 ?>"><?php if($c['centre_active']): ?><label class="check"><input type="checkbox" name="confirm_removal" value="1" required><?= e(tr('Confirm deactivation')) ?></label><?php endif; ?><button class="btn"><?= e(tr($c['centre_active']?'Deactivate':'Make available')) ?></button></form></article><?php endforeach; ?></div><?php if(!$available): ?><p><?= e(tr('Create a global course first.')) ?> <a href="courses.php?new=1"><?= e(tr('Add course')) ?></a></p><?php endif; ?></section><?php endif; ?>
<?php if(!$batch){page_footer();exit;}
$batchCourses=DB::all('SELECT c.*,bc.is_active AS batch_active FROM courses c JOIN batch_courses bc ON bc.course_id=c.id WHERE bc.batch_id=? ORDER BY c.name',[$batch]);
?>
<section class="card"><h2><?= e($selectedBatch['name']) ?> · <?= e(tr('Courses')) ?></h2><form method="post" class="form-grid"><?= csrf_field() ?><input type="hidden" name="action" value="batch_course"><input type="hidden" name="batch_id" value="<?= $batch ?>"><label><?= e(tr('Available global course')) ?><select name="course_id" required><?php foreach($available as $c): if(!$c['centre_active']||!$c['is_active'])continue; ?><option value="<?= (int)$c['id'] ?>"><?= e($c['name']) ?></option><?php endforeach; ?></select></label><div class="form-actions"><button class="btn btn-primary"><?= e(tr('Assign course to batch')) ?></button></div></form></section>
<?php foreach($batchCourses as $c): $subjects=DB::all('SELECT s.*,cs.is_active AS course_active,bs.is_active AS batch_active,cs.subject_id FROM course_subjects cs JOIN subjects s ON s.id=cs.subject_id LEFT JOIN batch_subjects bs ON bs.subject_id=s.id AND bs.course_id=cs.course_id AND bs.batch_id=? WHERE cs.course_id=? AND (EXISTS(SELECT 1 FROM centre_subjects available WHERE available.subject_id=s.id AND available.centre_id=?) OR bs.subject_id IS NOT NULL) ORDER BY s.name',[$batch,$c['id'],$centre]); ?>
<section class="card"><div class="card-heading"><h2><?= e($c['name']) ?></h2><span class="pill <?= $c['batch_active']?'ok':'' ?>"><?= e(tr($c['batch_active']?'Active':'inactive')) ?></span></div><form method="post" class="inline-form"><?= csrf_field() ?><input type="hidden" name="action" value="batch_course"><input type="hidden" name="batch_id" value="<?= $batch ?>"><input type="hidden" name="course_id" value="<?= (int)$c['id'] ?>"><input type="hidden" name="active" value="<?= $c['batch_active']?0:1 ?>"><?php if($c['batch_active']): ?><label class="check"><input type="checkbox" name="confirm_removal" value="1" required><?= e(tr('Confirm deactivation')) ?></label><?php endif; ?><button class="btn"><?= e(tr($c['batch_active']?'Deactivate course assignment':'Restore course assignment')) ?></button></form>
<form method="post" class="spaced" data-catalogue-form><?= csrf_field() ?><input type="hidden" name="action" value="batch_subjects"><input type="hidden" name="batch_id" value="<?= $batch ?>"><input type="hidden" name="course_id" value="<?= (int)$c['id'] ?>"><div class="assignment-columns"><?php foreach($subjects as $s): ?><label class="assignment-choice"><input type="checkbox" name="subject_ids[]" value="<?= (int)$s['id'] ?>"<?= checked((bool)$s['batch_active']) ?>><?= Images::thumbnail($s['cover_asset_id']??null,'',true) ?><span><?= e($s['name']) ?><small><?= e(tr($s['batch_active']?'Assigned':'Not assigned')) ?><?= !$s['course_active']||!$s['is_active']?' · '.e(tr('inactive')):'' ?></small></span></label><?php endforeach; ?></div><label class="check spaced"><input type="checkbox" name="confirm_removal" value="1"><?= e(tr('Confirm removal of unchecked subjects. History will be retained.')) ?></label><button class="btn btn-primary"><?= e(tr('Save batch subjects')) ?></button></form></section>
<?php endforeach; ?>
<section class="card"><h2><?= e(tr('Teacher batch assignments')) ?></h2><p class="muted"><?= e(tr('Choose an existing Teacher subject grant. Batch assignment never grants content or test management permissions.')) ?> <a href="teacher_assignments.php"><?= e(tr('Teacher subject grants')) ?></a></p>
<?php $teachers=DB::all("SELECT u.id,u.full_name FROM users u JOIN roles r ON r.id=u.role_id AND r.code='teacher' WHERE u.centre_id=? AND u.status='active' AND u.deleted_at IS NULL ORDER BY u.full_name",[$centre]);$tuples=DB::all('SELECT bs.course_id,bs.subject_id,c.name AS course,s.name AS subject FROM batch_subjects bs JOIN batch_courses bc ON bc.batch_id=bs.batch_id AND bc.course_id=bs.course_id AND bc.is_active=1 JOIN courses c ON c.id=bs.course_id AND c.is_active=1 JOIN subjects s ON s.id=bs.subject_id AND s.is_active=1 JOIN course_subjects cs ON cs.course_id=bs.course_id AND cs.subject_id=bs.subject_id AND cs.is_active=1 JOIN centre_courses cc ON cc.course_id=bs.course_id AND cc.centre_id=? AND cc.is_active=1 JOIN centre_subjects available ON available.centre_id=cc.centre_id AND available.subject_id=bs.subject_id WHERE bs.batch_id=? AND bs.is_active=1 ORDER BY c.name,s.name',[$centre,$batch]); ?>
<?php foreach($tuples as $t): ?><form method="post" class="filter-bar"><?= csrf_field() ?><input type="hidden" name="action" value="teacher_tuple"><input type="hidden" name="batch_id" value="<?= $batch ?>"><input type="hidden" name="course_id" value="<?= (int)$t['course_id'] ?>"><input type="hidden" name="subject_id" value="<?= (int)$t['subject_id'] ?>"><strong><?= e($t['course'].' · '.$t['subject']) ?></strong><label><?= e(tr('Teacher')) ?><select name="teacher_id" required><?php foreach($teachers as $teacher): if(!DB::val('SELECT id FROM teacher_subjects WHERE teacher_id=? AND subject_id=?',[$teacher['id'],$t['subject_id']]))continue; ?><option value="<?= (int)$teacher['id'] ?>"><?= e($teacher['full_name']) ?></option><?php endforeach; ?></select></label><button class="btn"><?= e(tr('Assign Teacher')) ?></button></form><?php endforeach; ?>
<?php $assigned=DB::all('SELECT t.*,u.full_name,c.name AS course,s.name AS subject FROM teacher_batch_subjects t JOIN users u ON u.id=t.teacher_id AND u.centre_id=? JOIN courses c ON c.id=t.course_id JOIN subjects s ON s.id=t.subject_id WHERE t.batch_id=? ORDER BY u.full_name,c.name,s.name',[$centre,$batch]);foreach($assigned as $t): ?><form method="post" class="filter-bar"><?= csrf_field() ?><input type="hidden" name="action" value="teacher_tuple"><input type="hidden" name="teacher_id" value="<?= (int)$t['teacher_id'] ?>"><input type="hidden" name="batch_id" value="<?= $batch ?>"><input type="hidden" name="course_id" value="<?= (int)$t['course_id'] ?>"><input type="hidden" name="subject_id" value="<?= (int)$t['subject_id'] ?>"><input type="hidden" name="active" value="<?= $t['is_active']?0:1 ?>"><span><?= e($t['full_name'].' · '.$t['course'].' · '.$t['subject']) ?> · <?= e(tr($t['is_active']?'Active':'inactive')) ?></span><?php if($t['is_active']): ?><label class="check"><input type="checkbox" name="confirm_removal" value="1" required><?= e(tr('Confirm deactivation')) ?></label><?php endif; ?><button class="btn"><?= e(tr($t['is_active']?'Deactivate':'Restore')) ?></button></form><?php endforeach; ?>
</section><?php page_footer();
